import * as THREE from 'three';
import { TEAM_BLUE, TEAM_RED } from './constants.js';
import { lambertFor } from './buildings.js';

// =====================================================================
// Villager model
//
// Loaded from assets/villager.glb, generated by tools/build_villager.py in
// Blender. Limbs are separate meshes pivoted at the hips and shoulders, so
// walking is animated by swinging them rather than by skinning.
// =====================================================================

// Brighter than the settlement roofs so walkers stand out on the terrain.
const TEAM_COLORS = {
  [TEAM_BLUE]: 0x4ab0ff,
  [TEAM_RED]:  0xff5050,
};

const LIMBS = ['leg_l', 'leg_r', 'arm_l', 'arm_r'];
export const VILLAGER_STRIDE = 7;  // walk-cycle radians per world unit travelled
const LEG_SWING = 0.6;
const ARM_SWING = 0.5;
export const PUNCH_RATE = 7;       // punch-cycle radians per second

let template = null;

export async function loadVillager(url = 'assets/villager.glb') {
  const { GLTFLoader } = await import('three/addons/loaders/GLTFLoader.js');
  const gltf = await new GLTFLoader().loadAsync(url);
  const obj = gltf.scene.getObjectByName('villager');
  if (!obj) throw new Error('villager.glb is missing the villager node');
  for (const name of ['body', ...LIMBS]) {
    if (!obj.getObjectByName(name)) throw new Error(`villager.glb is missing ${name}`);
  }
  template = obj;
}

// Build a villager for a team. Returns the root (origin at the feet) plus
// its limbs; geometry and materials are shared, so don't dispose them.
export function makeVillager(team) {
  if (!template) return makePlaceholder(team);
  const root = template.clone();
  root.position.set(0, 0, 0);
  root.traverse(o => {
    if (!o.isMesh) return;
    o.material = lambertFor(o.material, team, TEAM_COLORS);
    o.castShadow = true;
  });
  const limbs = {};
  for (const name of LIMBS) limbs[name] = root.getObjectByName(name);
  return { root, limbs };
}

const lerp = (a, b, t) => a + (b - a) * t;

// Fist extension over one punch cycle: a quick jab, then back to guard.
const jab = p => Math.max(0, Math.sin(p)) ** 3;

// Pose a villager by blending the walk cycle and the fighting stance.
//   walkPhase / stride: walk-cycle angle and strength (0 = standing still)
//   fightPhase / fight: punch-cycle angle and strength (0 = not fighting)
export function poseVillager({ root, limbs }, { walkPhase, stride, fightPhase, fight }) {
  // Fighting: alternate left/right jabs, leaning and twisting into each.
  const jl = jab(fightPhase), jr = jab(fightPhase + Math.PI);
  root.rotation.x = fight * (0.12 + 0.06 * (jl + jr));
  root.rotation.y = fight * 0.18 * (jr - jl);
  // Rise as the legs pass under the body when walking; bounce on the
  // toes when fighting. The caller positions an outer group, so the
  // root's own transform is free for this.
  root.position.y = lerp(
    Math.abs(Math.cos(walkPhase)) * 0.025 * stride,
    Math.abs(Math.sin(fightPhase)) * 0.018,
    fight,
  );
  if (!limbs.leg_l) return;

  const s = Math.sin(walkPhase) * stride;
  limbs.leg_l.rotation.x = lerp( s * LEG_SWING, -0.3,  fight);
  limbs.leg_r.rotation.x = lerp(-s * LEG_SWING,  0.25, fight);
  // Guard: fists raised in front of the chest and turned inwards; a jab
  // swings the arm level and straightens it.
  limbs.arm_l.rotation.x = lerp(-s * ARM_SWING, -0.9 - 0.65 * jl, fight);
  limbs.arm_r.rotation.x = lerp( s * ARM_SWING, -0.9 - 0.65 * jr, fight);
  limbs.arm_l.rotation.z = fight * -(0.35 - 0.25 * jl);
  limbs.arm_r.rotation.z = fight *  (0.35 - 0.25 * jr);
}

// Capsule fallback used when villager.glb failed to load.
const placeholderGeo = new THREE.CapsuleGeometry(0.18, 0.35, 4, 6);
function makePlaceholder(team) {
  const root = new THREE.Group();
  const mesh = new THREE.Mesh(placeholderGeo, lambertFor({ name: 'team' }, team, TEAM_COLORS));
  mesh.position.y = 0.36;
  mesh.castShadow = true;
  root.add(mesh);
  return { root, limbs: {} };
}
